public struct FfiConverterTypeLightFfiError: FfiConverterRustBuffer {
    typealias SwiftType = LightFfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LightFfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Failed(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LightFfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Failed(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


